create table if not exists public.workspaces(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null default 'Creator Command',created_at timestamptz not null default now());
create table if not exists public.platform_connections(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,platform text not null check(platform in ('youtube','tiktok','instagram','facebook')),external_account_id text not null,display_name text,username text,access_token_encrypted text,refresh_token_encrypted text,token_expires_at timestamptz,scopes text[],status text not null default 'connected',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,platform,external_account_id));
create table if not exists public.metric_snapshots(id uuid primary key default gen_random_uuid(),connection_id uuid not null references public.platform_connections(id) on delete cascade,captured_at timestamptz not null default now(),views bigint default 0,likes bigint default 0,comments bigint default 0,shares bigint default 0,followers bigint default 0,watch_time_seconds bigint default 0,raw jsonb not null default '{}'::jsonb);
create table if not exists public.content_items(id uuid primary key default gen_random_uuid(),connection_id uuid not null references public.platform_connections(id) on delete cascade,external_id text not null,title text,content_type text,permalink text,published_at timestamptz,views bigint default 0,likes bigint default 0,comments bigint default 0,shares bigint default 0,duration_seconds integer,raw jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(connection_id,external_id));
create table if not exists public.trends(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,topic text not null,state text not null,velocity numeric default 0,acceleration numeric default 0,relevance numeric default 0,saturation numeric default 0,score numeric default 0,metadata jsonb not null default '{}'::jsonb,observed_at timestamptz not null default now());
create table if not exists public.ideas(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,title text not null,description text,platforms text[],confidence numeric default 0,status text not null default 'new',source jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.sync_jobs(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,type text not null,status text not null default 'queued',platform text,started_at timestamptz,finished_at timestamptz,error text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.workspaces enable row level security; alter table public.platform_connections enable row level security; alter table public.metric_snapshots enable row level security; alter table public.content_items enable row level security; alter table public.trends enable row level security; alter table public.ideas enable row level security; alter table public.sync_jobs enable row level security;
create policy "workspace owner" on public.workspaces for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "connections owner" on public.platform_connections for all using(workspace_id in(select id from public.workspaces where owner_id=auth.uid())) with check(workspace_id in(select id from public.workspaces where owner_id=auth.uid()));
create policy "metrics owner" on public.metric_snapshots for all using(connection_id in(select id from public.platform_connections where workspace_id in(select id from public.workspaces where owner_id=auth.uid()))) with check(connection_id in(select id from public.platform_connections where workspace_id in(select id from public.workspaces where owner_id=auth.uid())));
create policy "content owner" on public.content_items for all using(connection_id in(select id from public.platform_connections where workspace_id in(select id from public.workspaces where owner_id=auth.uid()))) with check(connection_id in(select id from public.platform_connections where workspace_id in(select id from public.workspaces where owner_id=auth.uid())));
create policy "trends owner" on public.trends for all using(workspace_id in(select id from public.workspaces where owner_id=auth.uid())) with check(workspace_id in(select id from public.workspaces where owner_id=auth.uid()));
create policy "ideas owner" on public.ideas for all using(workspace_id in(select id from public.workspaces where owner_id=auth.uid())) with check(workspace_id in(select id from public.workspaces where owner_id=auth.uid()));
create policy "jobs owner" on public.sync_jobs for all using(workspace_id in(select id from public.workspaces where owner_id=auth.uid())) with check(workspace_id in(select id from public.workspaces where owner_id=auth.uid()));